/** A shell saves these generated bytes through its own user-controlled Save As. */
export type ArtifactDownloadPayload = {
  /** Suggested basename only; never an authorized filesystem destination. */
  filename?: string;
  /** Canonical FileReader data URL, with base64-encoded local file contents. */
  dataUrl: string;
};

export type ArtifactDownloadFailureReason = 'unsupported-url' | 'too-large' | 'read-failed';

/** Bound both in-frame serialization and trusted-shell decoding. */
export const MAX_ARTIFACT_DOWNLOAD_BYTES = 8 * 1024 * 1024;
export const MAX_ARTIFACT_DOWNLOAD_DATA_URL_CHARS =
  Math.ceil(MAX_ARTIFACT_DOWNLOAD_BYTES / 3) * 4 + 256;
